CREATE TABLE "generation_rights_erasure_preflights" (
  "workspace_id" text NOT NULL, "closure_id" text NOT NULL, "lease_id" text NOT NULL, "lease_fence" integer NOT NULL,
  "evidence_row_count" bigint NOT NULL, "snapshot_row_count" bigint NOT NULL, "retention_policy_revision" integer NOT NULL,
  "retention_rule_digest" text NOT NULL, "rights_set_mac" text NOT NULL, "signing_key_id" text NOT NULL,
  "audit_sequence" integer NOT NULL, "audit_event_id" text NOT NULL, "evaluated_at" timestamptz NOT NULL,
  "preflight_digest" text NOT NULL, "preflight_mac" text NOT NULL,
  CONSTRAINT "generation_rights_erasure_preflights_pk" PRIMARY KEY ("workspace_id","closure_id","lease_id","lease_fence"),
  CONSTRAINT "generation_rights_erasure_preflights_values_check" CHECK (
    "lease_id" ~ '^lease_[A-Za-z0-9]+$' AND "lease_fence">0 AND "evidence_row_count">=0 AND "snapshot_row_count">=0
    AND "retention_policy_revision">0 AND "retention_rule_digest" ~ '^sha256:[a-f0-9]{64}$'
    AND "rights_set_mac" ~ '^hmac-sha256:[a-f0-9]{64}$' AND "signing_key_id" ~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}$'
    AND "audit_sequence">0 AND "audit_event_id" ~ '^rights_preflight_[a-f0-9]{32}$'
    AND "preflight_digest" ~ '^sha256:[a-f0-9]{64}$' AND "preflight_mac" ~ '^hmac-sha256:[a-f0-9]{64}$')
);
CREATE TABLE "generation_rights_erasure_v2_bindings" (
  "workspace_id" text PRIMARY KEY, "closure_id" text NOT NULL, "preflight_digest" text NOT NULL,
  "tombstone_digest" text NOT NULL, "signing_key_id" text NOT NULL, "binding_mac" text NOT NULL,
  CONSTRAINT "generation_rights_erasure_v2_bindings_values_check" CHECK (
    "preflight_digest" ~ '^sha256:[a-f0-9]{64}$' AND "tombstone_digest" ~ '^sha256:[a-f0-9]{64}$'
    AND "signing_key_id" ~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}$' AND "binding_mac" ~ '^hmac-sha256:[a-f0-9]{64}$')
);
CREATE TABLE "generation_rights_retention_decisions" (
  "workspace_id" text NOT NULL, "closure_id" text NOT NULL, "lease_id" text NOT NULL, "lease_fence" integer NOT NULL,
  "attempt_digest" text NOT NULL, "retention_policy_revision" integer NOT NULL, "retention_revision_digest" text NOT NULL,
  "blocking_hold_ids" text[] NOT NULL, "signing_key_id" text NOT NULL, "decided_at" timestamptz NOT NULL,
  "decision_digest" text NOT NULL, "decision_mac" text NOT NULL,
  CONSTRAINT "generation_rights_retention_decisions_pk" PRIMARY KEY ("workspace_id","closure_id","lease_id","lease_fence"),
  CONSTRAINT "generation_rights_retention_decisions_values_check" CHECK (
    "lease_id" ~ '^lease_[A-Za-z0-9]+$' AND "lease_fence">0 AND "attempt_digest" ~ '^sha256:[a-f0-9]{64}$'
    AND "retention_policy_revision">0 AND "retention_revision_digest" ~ '^sha256:[a-f0-9]{64}$'
    AND pg_catalog.cardinality("blocking_hold_ids")>0 AND pg_catalog.array_position("blocking_hold_ids",NULL) IS NULL
    AND "signing_key_id" ~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}$'
    AND "decision_digest" ~ '^sha256:[a-f0-9]{64}$' AND "decision_mac" ~ '^hmac-sha256:[a-f0-9]{64}$')
);
CREATE TRIGGER "generation_rights_erasure_preflights_append_only" BEFORE UPDATE OR DELETE ON "generation_rights_erasure_preflights"
FOR EACH ROW EXECUTE FUNCTION public.prevent_generation_rights_erasure_proof_mutation();
CREATE TRIGGER "generation_rights_erasure_v2_bindings_append_only" BEFORE UPDATE OR DELETE ON "generation_rights_erasure_v2_bindings"
FOR EACH ROW EXECUTE FUNCTION public.prevent_generation_rights_erasure_proof_mutation();
CREATE TRIGGER "generation_rights_retention_decisions_append_only" BEFORE UPDATE OR DELETE ON "generation_rights_retention_decisions"
FOR EACH ROW EXECUTE FUNCTION public.prevent_generation_rights_erasure_proof_mutation();
-- An eligible preflight is the irreversible legal cutover for this evidence
-- set. Governance mutations use the same advisory lock, and direct SQL is
-- guarded here, so no later hold/policy change can race dependent deletion.
CREATE FUNCTION public.guard_generation_rights_cutover_governance_mutation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $guard$
DECLARE v_workspace_id text:=CASE WHEN TG_OP='DELETE' THEN OLD."workspace_id" ELSE NEW."workspace_id" END; v_kind text:=CASE WHEN TG_OP='DELETE' THEN OLD."kind" ELSE NEW."kind" END;
BEGIN
  IF TG_OP='UPDATE' AND (OLD."workspace_id" IS DISTINCT FROM NEW."workspace_id" OR OLD."kind" IS DISTINCT FROM NEW."kind") THEN RAISE EXCEPTION 'governance resource Workspace and kind are immutable'; END IF;
  IF v_kind NOT IN ('retention_policy','retention_hold') THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('workspace-governance:'||v_workspace_id,0));
  IF EXISTS (SELECT 1 FROM public."generation_rights_erasure_preflights" WHERE "workspace_id"=v_workspace_id)
    AND NOT EXISTS (SELECT 1 FROM public."generation_rights_erasure_tombstones" WHERE "workspace_id"=v_workspace_id) THEN
    RAISE EXCEPTION 'generation rights erasure legal cutover blocks retention mutation';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END; $guard$;
CREATE TRIGGER "workspace_governance_generation_rights_cutover_guard" BEFORE INSERT OR UPDATE OR DELETE ON "workspace_governance_resources"
FOR EACH ROW EXECUTE FUNCTION public.guard_generation_rights_cutover_governance_mutation();
--> statement-breakpoint
CREATE FUNCTION public.tasmeemai_try_canonical_timestamptz(value text) RETURNS timestamptz
LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog,pg_temp AS $canonical_timestamp$
DECLARE parsed timestamptz;
BEGIN
  IF value !~ '^[0-9]{4}-(0[1-9]|1[0-2])-([0-2][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9][.][0-9]{3}Z$' THEN RETURN NULL; END IF;
  parsed:=value::timestamptz;
  IF NOT pg_catalog.isfinite(parsed) OR pg_catalog.to_char(parsed AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') IS DISTINCT FROM value THEN RETURN NULL; END IF;
  RETURN parsed;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END; $canonical_timestamp$;
