CREATE FUNCTION public.preflight_closed_workspace_generation_rights(p_workspace_id text,p_closure_id text,p_lease_id text,p_lease_fence integer)
RETURNS TABLE (outcome text,preflight_digest text,evidence_row_count bigint,snapshot_row_count bigint,retention_policy_revision integer,retention_revision jsonb,signing_key_id text,audit_sequence integer,audit_event_id text,blocking_hold_ids text[],eligible_at timestamptz,evaluated_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $preflight$
DECLARE
  v_now timestamptz; v_key text:=pg_catalog.current_setting('app.generation_rights_erasure_hmac_key',true); v_key_id text:=pg_catalog.current_setting('app.generation_rights_erasure_hmac_key_id',true);
  v_closure record; v_policy record; v_revision jsonb; v_rule jsonb; v_count integer; v_duration integer; v_recoverable integer; v_floor integer; v_latest timestamptz; v_eligible timestamptz; v_blocking_hold_ids text[];
  v_evidence bigint; v_snapshots bigint; v_rights_mac text; v_rule_digest text; v_revision_digest text; v_sequence integer; v_event_id text; v_receipt_key text; v_unsigned jsonb; v_digest text; v_mac text; v_expected_audit jsonb; v_expected_result jsonb; v_attempt public."generation_rights_erasure_attempts"%ROWTYPE; v_existing public."generation_rights_erasure_preflights"%ROWTYPE; v_binding public."generation_rights_erasure_v2_bindings"%ROWTYPE; v_decision public."generation_rights_retention_decisions"%ROWTYPE; v_tombstone public."generation_rights_erasure_tombstones"%ROWTYPE; v_erasure record;
BEGIN
  IF p_workspace_id IS NULL OR p_workspace_id !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}$' OR p_closure_id IS NULL OR p_closure_id !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}$' OR p_lease_id IS NULL OR p_lease_id !~ '^lease_[A-Za-z0-9]+$' OR p_lease_fence IS NULL OR p_lease_fence<1 THEN RAISE EXCEPTION 'invalid generation rights preflight identity'; END IF;
  IF v_key IS NULL OR pg_catalog.octet_length(v_key)<32 OR v_key_id IS NULL OR v_key_id !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}$' THEN RAISE EXCEPTION 'generation rights erasure signing authority unavailable'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('workspace-governance:'||p_workspace_id,0));
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('workspace-audit:'||p_workspace_id,0));
  v_now:=pg_catalog.clock_timestamp();
  SELECT "status","body" INTO v_closure FROM public."workspace_governance_resources" WHERE "workspace_id"=p_workspace_id AND "kind"='workspace_closure' AND "id"=p_closure_id FOR UPDATE;
  IF NOT FOUND OR v_closure."status" IS DISTINCT FROM 'erasure_running' OR v_closure."body"->>'erasureScheduled' IS DISTINCT FROM 'true' OR v_closure."body"->'lease'->>'id' IS DISTINCT FROM p_lease_id OR public.tasmeemai_try_positive_integer(v_closure."body"->'lease'->>'fence') IS DISTINCT FROM p_lease_fence OR public.tasmeemai_try_canonical_timestamptz(v_closure."body"->'lease'->>'expiresAt') IS NULL OR public.tasmeemai_try_canonical_timestamptz(v_closure."body"->'lease'->>'expiresAt')<=v_now THEN RAISE EXCEPTION 'current fenced workspace closure lease required'; END IF;
  SELECT * INTO v_binding FROM public."generation_rights_erasure_v2_bindings" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id;
  IF FOUND THEN
    SELECT * INTO v_existing FROM public."generation_rights_erasure_preflights" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id AND "preflight_digest"=v_binding."preflight_digest";
    IF NOT FOUND OR v_binding."signing_key_id"<>v_key_id OR v_existing."signing_key_id"<>v_key_id OR v_binding."binding_mac" IS DISTINCT FROM 'hmac-sha256:'||pg_catalog.encode(public.tasmeemai_pgcrypto_hmac_sha256(pg_catalog.convert_to('generation-rights-erasure-v2-binding/v1:'||pg_catalog.jsonb_build_object('workspaceId',p_workspace_id,'closureId',p_closure_id,'preflightDigest',v_binding."preflight_digest",'tombstoneDigest',v_binding."tombstone_digest",'signingKeyId',v_binding."signing_key_id")::text,'UTF8'),pg_catalog.convert_to(v_key,'UTF8')),'hex') OR NOT EXISTS (SELECT 1 FROM public."generation_rights_erasure_tombstones" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id AND "tombstone_digest"=v_binding."tombstone_digest") THEN RAISE EXCEPTION 'generation rights completed preflight binding invalid'; END IF;
    v_unsigned:=pg_catalog.jsonb_build_object('schema','generation-rights-erasure-preflight/v1','workspaceId',p_workspace_id,'closureId',p_closure_id,'leaseId',v_existing."lease_id",'leaseFence',v_existing."lease_fence",'evidenceRowCount',v_existing."evidence_row_count",'snapshotRowCount',v_existing."snapshot_row_count",'retentionPolicyRevision',v_existing."retention_policy_revision",'retentionRuleDigest',v_existing."retention_rule_digest",'rightsSetMac',v_existing."rights_set_mac",'signingKeyId',v_existing."signing_key_id",'auditSequence',v_existing."audit_sequence",'auditEventId',v_existing."audit_event_id",'evaluatedAt',pg_catalog.to_char(v_existing."evaluated_at" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
    v_digest:='sha256:'||pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_unsigned::text,'UTF8')),'hex'); v_mac:='hmac-sha256:'||pg_catalog.encode(public.tasmeemai_pgcrypto_hmac_sha256(pg_catalog.convert_to('generation-rights-erasure-preflight-mac/v1:'||v_digest,'UTF8'),pg_catalog.convert_to(v_key,'UTF8')),'hex');
    v_receipt_key:='rights-preflight-'||pg_catalog.substr(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_existing."closure_id"||':'||v_existing."lease_id",'UTF8')),'hex'),1,24)||'-'||v_existing."lease_fence"::text;
    v_expected_result:=pg_catalog.jsonb_build_object('schema','generation-rights-erasure-preflight-result/v1','closureId',p_closure_id,'preflightDigest',v_digest,'outcome','eligible');
    v_expected_audit:=pg_catalog.jsonb_build_object('schema','workspace-audit-event/v1','id',v_existing."audit_event_id",'workspaceId',p_workspace_id,'sequence',v_existing."audit_sequence",'actor',pg_catalog.jsonb_build_object('kind','system','id','tasmeemai:workspace-closure-worker@1'),'capability','workspace_closures.preflight_generation_rights@1','action','preflight_generation_rights_erasure','resource',pg_catalog.jsonb_build_object('kind','workspace_closure','id',p_closure_id),'outcome','accepted','redactedDetails',pg_catalog.jsonb_build_object('preflightDigest',v_digest,'signingKeyId',v_existing."signing_key_id"),'occurredAt',pg_catalog.to_char(v_existing."evaluated_at" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
    IF v_existing."preflight_digest"<>v_digest OR v_existing."preflight_mac"<>v_mac OR NOT EXISTS (SELECT 1 FROM public."workspace_audit_trail_events" WHERE "workspace_id"=p_workspace_id AND "sequence"=v_existing."audit_sequence" AND "id"=v_existing."audit_event_id" AND "event"=v_expected_audit AND "occurred_at"=v_existing."evaluated_at") OR NOT EXISTS (SELECT 1 FROM public."workspace_governance_mutation_receipts" WHERE "workspace_id"=p_workspace_id AND "capability"='workspace_closures.preflight_generation_rights@1' AND "idempotency_key"=v_receipt_key AND "request_digest"=v_digest AND "actor_identity" IS NULL AND "auth_context_digest" IS NULL AND "result"=v_expected_result AND "created_at"=v_existing."evaluated_at") THEN RAISE EXCEPTION 'generation rights completed preflight proof invalid'; END IF;
    RETURN QUERY SELECT 'eligible',v_existing."preflight_digest",v_existing."evidence_row_count",v_existing."snapshot_row_count",v_existing."retention_policy_revision",NULL::jsonb,v_existing."signing_key_id",v_existing."audit_sequence",v_existing."audit_event_id",ARRAY[]::text[],NULL::timestamptz,v_existing."evaluated_at"; RETURN;
  END IF;
  -- Upgrade/lost-response recovery: validate the complete 0114 proof through
  -- its own replay path, then adopt its original nonzero counts and manifest
  -- into a new lease-bound v2 preflight. Never infer an empty erased set.
  SELECT * INTO v_tombstone FROM public."generation_rights_erasure_tombstones" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id;
  IF FOUND THEN
    SELECT * INTO v_erasure FROM public.erase_closed_workspace_generation_rights(p_workspace_id,p_closure_id,p_lease_id,p_lease_fence);
    IF v_erasure.outcome IS DISTINCT FROM 'replayed' OR v_erasure.tombstone_digest IS DISTINCT FROM v_tombstone."tombstone_digest" THEN RAISE EXCEPTION 'legacy generation rights tombstone adoption failed'; END IF;
    v_evidence:=v_tombstone."evidence_row_count"; v_snapshots:=v_tombstone."snapshot_row_count"; v_rule_digest:=v_tombstone."retention_rule_digest"; v_rights_mac:=v_tombstone."erasure_manifest_mac";
    SELECT * INTO v_existing FROM public."generation_rights_erasure_preflights" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id AND "lease_id"=p_lease_id AND "lease_fence"=p_lease_fence;
    IF FOUND THEN
      v_unsigned:=pg_catalog.jsonb_build_object('schema','generation-rights-erasure-preflight/v1','workspaceId',p_workspace_id,'closureId',p_closure_id,'leaseId',p_lease_id,'leaseFence',p_lease_fence,'evidenceRowCount',v_existing."evidence_row_count",'snapshotRowCount',v_existing."snapshot_row_count",'retentionPolicyRevision',v_existing."retention_policy_revision",'retentionRuleDigest',v_existing."retention_rule_digest",'rightsSetMac',v_existing."rights_set_mac",'signingKeyId',v_existing."signing_key_id",'auditSequence',v_existing."audit_sequence",'auditEventId',v_existing."audit_event_id",'evaluatedAt',pg_catalog.to_char(v_existing."evaluated_at" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
      v_digest:='sha256:'||pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_unsigned::text,'UTF8')),'hex'); v_mac:='hmac-sha256:'||pg_catalog.encode(public.tasmeemai_pgcrypto_hmac_sha256(pg_catalog.convert_to('generation-rights-erasure-preflight-mac/v1:'||v_digest,'UTF8'),pg_catalog.convert_to(v_key,'UTF8')),'hex');
      v_receipt_key:='rights-preflight-'||pg_catalog.substr(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_closure_id||':'||p_lease_id,'UTF8')),'hex'),1,24)||'-'||p_lease_fence::text;
      v_expected_result:=pg_catalog.jsonb_build_object('schema','generation-rights-erasure-preflight-result/v1','closureId',p_closure_id,'preflightDigest',v_digest,'outcome','eligible');
      v_expected_audit:=pg_catalog.jsonb_build_object('schema','workspace-audit-event/v1','id',v_existing."audit_event_id",'workspaceId',p_workspace_id,'sequence',v_existing."audit_sequence",'actor',pg_catalog.jsonb_build_object('kind','system','id','tasmeemai:workspace-closure-worker@1'),'capability','workspace_closures.preflight_generation_rights@1','action','preflight_generation_rights_erasure','resource',pg_catalog.jsonb_build_object('kind','workspace_closure','id',p_closure_id),'outcome','accepted','redactedDetails',pg_catalog.jsonb_build_object('preflightDigest',v_digest,'signingKeyId',v_existing."signing_key_id"),'occurredAt',pg_catalog.to_char(v_existing."evaluated_at" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
      IF v_existing."evidence_row_count"<>v_evidence OR v_existing."snapshot_row_count"<>v_snapshots OR v_existing."retention_policy_revision"<>v_tombstone."retention_policy_revision" OR v_existing."retention_rule_digest"<>v_rule_digest OR v_existing."rights_set_mac"<>v_rights_mac OR v_existing."signing_key_id"<>v_tombstone."signing_key_id" OR v_existing."preflight_digest"<>v_digest OR v_existing."preflight_mac"<>v_mac OR NOT EXISTS (SELECT 1 FROM public."workspace_audit_trail_events" WHERE "workspace_id"=p_workspace_id AND "sequence"=v_existing."audit_sequence" AND "id"=v_existing."audit_event_id" AND "event"=v_expected_audit AND "occurred_at"=v_existing."evaluated_at") OR NOT EXISTS (SELECT 1 FROM public."workspace_governance_mutation_receipts" WHERE "workspace_id"=p_workspace_id AND "capability"='workspace_closures.preflight_generation_rights@1' AND "idempotency_key"=v_receipt_key AND "request_digest"=v_digest AND "actor_identity" IS NULL AND "auth_context_digest" IS NULL AND "result"=v_expected_result AND "created_at"=v_existing."evaluated_at") THEN RAISE EXCEPTION 'legacy generation rights preflight replay invalid'; END IF;
      RETURN QUERY SELECT 'eligible',v_existing."preflight_digest",v_existing."evidence_row_count",v_existing."snapshot_row_count",v_existing."retention_policy_revision",NULL::jsonb,v_existing."signing_key_id",v_existing."audit_sequence",v_existing."audit_event_id",ARRAY[]::text[],NULL::timestamptz,v_existing."evaluated_at"; RETURN;
    END IF;
    SELECT coalesce(pg_catalog.max("sequence"),0)+1 INTO v_sequence FROM public."workspace_audit_trail_events" WHERE "workspace_id"=p_workspace_id;
    v_event_id:='rights_preflight_'||pg_catalog.substr(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_workspace_id||':'||p_closure_id||':'||p_lease_id||':'||p_lease_fence::text,'UTF8')),'hex'),1,32);
    v_unsigned:=pg_catalog.jsonb_build_object('schema','generation-rights-erasure-preflight/v1','workspaceId',p_workspace_id,'closureId',p_closure_id,'leaseId',p_lease_id,'leaseFence',p_lease_fence,'evidenceRowCount',v_evidence,'snapshotRowCount',v_snapshots,'retentionPolicyRevision',v_tombstone."retention_policy_revision",'retentionRuleDigest',v_rule_digest,'rightsSetMac',v_rights_mac,'signingKeyId',v_tombstone."signing_key_id",'auditSequence',v_sequence,'auditEventId',v_event_id,'evaluatedAt',pg_catalog.to_char(v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
    v_digest:='sha256:'||pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_unsigned::text,'UTF8')),'hex'); v_mac:='hmac-sha256:'||pg_catalog.encode(public.tasmeemai_pgcrypto_hmac_sha256(pg_catalog.convert_to('generation-rights-erasure-preflight-mac/v1:'||v_digest,'UTF8'),pg_catalog.convert_to(v_key,'UTF8')),'hex');
    INSERT INTO public."generation_rights_erasure_preflights" VALUES (p_workspace_id,p_closure_id,p_lease_id,p_lease_fence,v_evidence,v_snapshots,v_tombstone."retention_policy_revision",v_rule_digest,v_rights_mac,v_tombstone."signing_key_id",v_sequence,v_event_id,v_now,v_digest,v_mac);
    INSERT INTO public."workspace_governance_mutation_receipts" ("workspace_id","capability","idempotency_key","request_digest","actor_identity","auth_context_digest","result","created_at") VALUES (p_workspace_id,'workspace_closures.preflight_generation_rights@1','rights-preflight-'||pg_catalog.substr(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_closure_id||':'||p_lease_id,'UTF8')),'hex'),1,24)||'-'||p_lease_fence::text,v_digest,NULL,NULL,pg_catalog.jsonb_build_object('schema','generation-rights-erasure-preflight-result/v1','closureId',p_closure_id,'preflightDigest',v_digest,'outcome','eligible'),v_now);
    INSERT INTO public."workspace_audit_trail_events" ("workspace_id","sequence","id","event","occurred_at") VALUES (p_workspace_id,v_sequence,v_event_id,pg_catalog.jsonb_build_object('schema','workspace-audit-event/v1','id',v_event_id,'workspaceId',p_workspace_id,'sequence',v_sequence,'actor',pg_catalog.jsonb_build_object('kind','system','id','tasmeemai:workspace-closure-worker@1'),'capability','workspace_closures.preflight_generation_rights@1','action','preflight_generation_rights_erasure','resource',pg_catalog.jsonb_build_object('kind','workspace_closure','id',p_closure_id),'outcome','accepted','redactedDetails',pg_catalog.jsonb_build_object('preflightDigest',v_digest,'signingKeyId',v_tombstone."signing_key_id"),'occurredAt',pg_catalog.to_char(v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),v_now);
    RETURN QUERY SELECT 'eligible',v_digest,v_evidence,v_snapshots,v_tombstone."retention_policy_revision",NULL::jsonb,v_tombstone."signing_key_id",v_sequence,v_event_id,ARRAY[]::text[],NULL::timestamptz,v_now; RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public."workspaces" WHERE "id"=p_workspace_id AND "deleted_at" IS NULL FOR SHARE) THEN RAISE EXCEPTION 'open canonical workspace required during closure erasure'; END IF;
  IF pg_catalog.jsonb_typeof(v_closure."body"->'accessRevocationEvidence') IS DISTINCT FROM 'object' OR v_closure."body"->'accessRevocationEvidence'->>'schema' IS DISTINCT FROM 'workspace-access-revocation-evidence/v1' OR pg_catalog.jsonb_typeof(v_closure."body"->'accessRevocationEvidence'->'externalEffects') IS DISTINCT FROM 'array' OR EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(v_closure."body"->'accessRevocationEvidence'->'externalEffects') effect WHERE pg_catalog.jsonb_typeof(effect) IS DISTINCT FROM 'object' OR coalesce(effect->>'state','') NOT IN ('deleted','not_found') OR coalesce(effect->>'evidenceRef','')='') THEN
