  v_event_id:='rights_preflight_'||pg_catalog.substr(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_workspace_id||':'||p_closure_id||':'||p_lease_id||':'||p_lease_fence::text,'UTF8')),'hex'),1,32);
  v_unsigned:=pg_catalog.jsonb_build_object('schema','generation-rights-erasure-preflight/v1','workspaceId',p_workspace_id,'closureId',p_closure_id,'leaseId',p_lease_id,'leaseFence',p_lease_fence,'evidenceRowCount',v_evidence,'snapshotRowCount',v_snapshots,'retentionPolicyRevision',(v_policy."body"->>'activeRevision')::integer,'retentionRuleDigest',v_rule_digest,'rightsSetMac',v_rights_mac,'signingKeyId',v_key_id,'auditSequence',v_sequence,'auditEventId',v_event_id,'evaluatedAt',pg_catalog.to_char(v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  v_digest:='sha256:'||pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_unsigned::text,'UTF8')),'hex'); v_mac:='hmac-sha256:'||pg_catalog.encode(public.tasmeemai_pgcrypto_hmac_sha256(pg_catalog.convert_to('generation-rights-erasure-preflight-mac/v1:'||v_digest,'UTF8'),pg_catalog.convert_to(v_key,'UTF8')),'hex');
  INSERT INTO public."generation_rights_erasure_preflights" VALUES (p_workspace_id,p_closure_id,p_lease_id,p_lease_fence,v_evidence,v_snapshots,(v_policy."body"->>'activeRevision')::integer,v_rule_digest,v_rights_mac,v_key_id,v_sequence,v_event_id,v_now,v_digest,v_mac);
  INSERT INTO public."workspace_governance_mutation_receipts" ("workspace_id","capability","idempotency_key","request_digest","actor_identity","auth_context_digest","result","created_at") VALUES (p_workspace_id,'workspace_closures.preflight_generation_rights@1','rights-preflight-'||pg_catalog.substr(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_closure_id||':'||p_lease_id,'UTF8')),'hex'),1,24)||'-'||p_lease_fence::text,v_digest,NULL,NULL,pg_catalog.jsonb_build_object('schema','generation-rights-erasure-preflight-result/v1','closureId',p_closure_id,'preflightDigest',v_digest,'outcome','eligible'),v_now);
  INSERT INTO public."workspace_audit_trail_events" ("workspace_id","sequence","id","event","occurred_at") VALUES (p_workspace_id,v_sequence,v_event_id,pg_catalog.jsonb_build_object('schema','workspace-audit-event/v1','id',v_event_id,'workspaceId',p_workspace_id,'sequence',v_sequence,'actor',pg_catalog.jsonb_build_object('kind','system','id','tasmeemai:workspace-closure-worker@1'),'capability','workspace_closures.preflight_generation_rights@1','action','preflight_generation_rights_erasure','resource',pg_catalog.jsonb_build_object('kind','workspace_closure','id',p_closure_id),'outcome','accepted','redactedDetails',pg_catalog.jsonb_build_object('preflightDigest',v_digest,'signingKeyId',v_key_id),'occurredAt',pg_catalog.to_char(v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),v_now);
  RETURN QUERY SELECT 'eligible',v_digest,v_evidence,v_snapshots,(v_policy."body"->>'activeRevision')::integer,pg_catalog.jsonb_build_object('revision',v_revision,'digest',v_revision_digest),v_key_id,v_sequence,v_event_id,ARRAY[]::text[],NULL::timestamptz,v_now;
END; $preflight$;
--> statement-breakpoint
CREATE FUNCTION public.erase_closed_workspace_generation_rights_v2(p_workspace_id text,p_closure_id text,p_lease_id text,p_lease_fence integer,p_preflight_digest text)
RETURNS TABLE (schema_version text,outcome text,tombstone_digest text,evidence_row_count bigint,snapshot_row_count bigint,erased_at timestamptz,signing_key_id text,audit_sequence integer,audit_event_id text,preflight_digest text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $erase_v2$
DECLARE v_preflight record; v_erasure record; v_tombstone public."generation_rights_erasure_tombstones"%ROWTYPE; v_binding public."generation_rights_erasure_v2_bindings"%ROWTYPE; v_key text:=pg_catalog.current_setting('app.generation_rights_erasure_hmac_key',true); v_binding_mac text;
BEGIN
  SELECT * INTO v_preflight FROM public.preflight_closed_workspace_generation_rights(p_workspace_id,p_closure_id,p_lease_id,p_lease_fence);
  IF v_preflight.outcome IS DISTINCT FROM 'eligible' OR v_preflight.preflight_digest IS DISTINCT FROM p_preflight_digest THEN
    RETURN QUERY SELECT 'generation-rights-erasure-result/v2',v_preflight.outcome,NULL::text,0::bigint,0::bigint,NULL::timestamptz,v_preflight.signing_key_id,v_preflight.audit_sequence,v_preflight.audit_event_id,v_preflight.preflight_digest; RETURN;
  END IF;
  SELECT * INTO v_erasure FROM public.erase_closed_workspace_generation_rights(p_workspace_id,p_closure_id,p_lease_id,p_lease_fence);
  IF v_erasure.outcome NOT IN ('erased','replayed') THEN RETURN QUERY SELECT 'generation-rights-erasure-result/v2',v_erasure.outcome,NULL::text,0::bigint,0::bigint,v_erasure.erased_at,v_preflight.signing_key_id,v_preflight.audit_sequence,v_preflight.audit_event_id,v_preflight.preflight_digest; RETURN; END IF;
  SELECT * INTO v_tombstone FROM public."generation_rights_erasure_tombstones" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id;
  IF NOT FOUND OR v_tombstone."tombstone_digest" IS DISTINCT FROM v_erasure.tombstone_digest THEN RAISE EXCEPTION 'generation rights v2 result binding unavailable'; END IF;
  v_binding_mac:='hmac-sha256:'||pg_catalog.encode(public.tasmeemai_pgcrypto_hmac_sha256(pg_catalog.convert_to('generation-rights-erasure-v2-binding/v1:'||pg_catalog.jsonb_build_object('workspaceId',p_workspace_id,'closureId',p_closure_id,'preflightDigest',v_preflight.preflight_digest,'tombstoneDigest',v_tombstone."tombstone_digest",'signingKeyId',v_tombstone."signing_key_id")::text,'UTF8'),pg_catalog.convert_to(v_key,'UTF8')),'hex');
  SELECT * INTO v_binding FROM public."generation_rights_erasure_v2_bindings" WHERE "workspace_id"=p_workspace_id;
  IF FOUND THEN
    IF v_binding."closure_id"<>p_closure_id OR v_binding."preflight_digest"<>v_preflight.preflight_digest OR v_binding."tombstone_digest"<>v_tombstone."tombstone_digest" OR v_binding."signing_key_id"<>v_tombstone."signing_key_id" OR v_binding."binding_mac"<>v_binding_mac THEN RAISE EXCEPTION 'generation rights v2 replay binding invalid'; END IF;
  ELSE
    INSERT INTO public."generation_rights_erasure_v2_bindings" VALUES (p_workspace_id,p_closure_id,v_preflight.preflight_digest,v_tombstone."tombstone_digest",v_tombstone."signing_key_id",v_binding_mac);
  END IF;
  RETURN QUERY SELECT 'generation-rights-erasure-result/v2',v_erasure.outcome,v_tombstone."tombstone_digest",v_tombstone."evidence_row_count",v_tombstone."snapshot_row_count",v_tombstone."erased_at",v_tombstone."signing_key_id",v_tombstone."audit_sequence",v_tombstone."audit_event_id",v_preflight.preflight_digest;
END; $erase_v2$;
--> statement-breakpoint
CREATE FUNCTION public.generation_rights_erasure_signing_key_id_v2(p_workspace_id text,p_closure_id text,p_lease_id text,p_lease_fence integer,p_outcome_code text)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $lookup$
DECLARE v_key_id text; v_count integer;
BEGIN
  IF p_workspace_id IS NULL OR p_closure_id IS NULL OR p_lease_id IS NULL OR p_lease_id !~ '^lease_[A-Za-z0-9]+$' OR p_lease_fence IS NULL OR p_lease_fence<1 THEN RAISE EXCEPTION 'invalid generation rights erasure replay identity'; END IF;
  SELECT "signing_key_id" INTO v_key_id FROM public."generation_rights_erasure_tombstones" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id; IF FOUND THEN RETURN v_key_id; END IF;
  SELECT pg_catalog.count(DISTINCT "signing_key_id"),pg_catalog.min("signing_key_id") INTO v_count,v_key_id FROM (
    SELECT "signing_key_id" FROM public."generation_rights_erasure_attempts" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id AND "lease_id"=p_lease_id AND "lease_fence"=p_lease_fence AND "outcome_code"=p_outcome_code
    UNION ALL SELECT "signing_key_id" FROM public."generation_rights_erasure_preflights" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id AND "lease_id"=p_lease_id AND "lease_fence"=p_lease_fence
    UNION ALL SELECT "signing_key_id" FROM public."generation_rights_retention_decisions" WHERE "workspace_id"=p_workspace_id AND "closure_id"=p_closure_id AND "lease_id"=p_lease_id AND "lease_fence"=p_lease_fence) keys;
  IF v_count>1 THEN RAISE EXCEPTION 'ambiguous generation rights erasure signing key'; END IF; RETURN v_key_id;
END; $lookup$;
--> statement-breakpoint
REVOKE EXECUTE ON FUNCTION public.erase_closed_workspace_generation_rights(text,text,text,integer) FROM tasmeemai_workspace_closure_worker;
REVOKE ALL ON FUNCTION public.guard_generation_rights_cutover_governance_mutation(), public.tasmeemai_try_canonical_timestamptz(text), public.preflight_closed_workspace_generation_rights(text,text,text,integer), public.erase_closed_workspace_generation_rights_v2(text,text,text,integer,text), public.generation_rights_erasure_signing_key_id_v2(text,text,text,integer,text) FROM PUBLIC;
GRANT SELECT,INSERT ON TABLE "generation_rights_erasure_preflights", "generation_rights_erasure_v2_bindings", "generation_rights_retention_decisions" TO tasmeemai_generation_rights_eraser_owner;
GRANT EXECUTE ON FUNCTION public.preflight_closed_workspace_generation_rights(text,text,text,integer), public.erase_closed_workspace_generation_rights_v2(text,text,text,integer,text), public.generation_rights_erasure_signing_key_id_v2(text,text,text,integer,text) TO tasmeemai_workspace_closure_worker;
REVOKE ALL ON TABLE "generation_rights_erasure_preflights", "generation_rights_erasure_v2_bindings", "generation_rights_retention_decisions" FROM PUBLIC, tasmeemai_workspace_closure_worker;
--> statement-breakpoint
DO $ownership$
DECLARE had_membership boolean:=pg_catalog.pg_has_role(CURRENT_USER,'tasmeemai_generation_rights_eraser_owner','MEMBER');
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE r.rolname='tasmeemai_generation_rights_eraser_owner') THEN RAISE EXCEPTION 'generation rights eraser owner role must not have members'; END IF;
  IF NOT had_membership THEN GRANT tasmeemai_generation_rights_eraser_owner TO CURRENT_USER; END IF;
  GRANT CREATE ON SCHEMA public TO tasmeemai_generation_rights_eraser_owner;
  ALTER FUNCTION public.preflight_closed_workspace_generation_rights(text,text,text,integer) OWNER TO tasmeemai_generation_rights_eraser_owner;
  ALTER FUNCTION public.erase_closed_workspace_generation_rights_v2(text,text,text,integer,text) OWNER TO tasmeemai_generation_rights_eraser_owner;
  ALTER FUNCTION public.generation_rights_erasure_signing_key_id_v2(text,text,text,integer,text) OWNER TO tasmeemai_generation_rights_eraser_owner;
  ALTER FUNCTION public.guard_generation_rights_cutover_governance_mutation() OWNER TO tasmeemai_generation_rights_eraser_owner;
  ALTER FUNCTION public.tasmeemai_try_canonical_timestamptz(text) OWNER TO tasmeemai_generation_rights_eraser_owner;
  REVOKE CREATE ON SCHEMA public FROM tasmeemai_generation_rights_eraser_owner;
  IF NOT had_membership THEN REVOKE tasmeemai_generation_rights_eraser_owner FROM CURRENT_USER; END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE r.rolname='tasmeemai_generation_rights_eraser_owner') THEN RAISE EXCEPTION 'generation rights eraser owner role retained an unexpected member'; END IF;
END;
$ownership$;
--> statement-breakpoint
DO $final_role_posture$
BEGIN
  IF pg_catalog.has_schema_privilege('tasmeemai_generation_rights_eraser_owner','public','CREATE') OR pg_catalog.has_schema_privilege('tasmeemai_workspace_closure_worker','public','CREATE') THEN RAISE EXCEPTION 'generation rights erasure roles must not create objects in public'; END IF;
END;
$final_role_posture$;
